import type { ModelScanStage } from "@/components/ui/model-scan-primitive"

type ModelScanLabels = {
  /** The 3D model's name once it shows, unless `modelAlt` names it. */
  model: string
  /** What each stage is doing: the progress label, and what screen readers hear when it starts. */
  stage: Record<Exclude<ModelScanStage, "photo" | "error">, string>
  /** Under the stage's label while working: `step` of `steps` (4: detecting to ready). */
  step: (step: number, steps: number) => string
  /** The button that starts a run from the photo, with `onStart`. */
  start: string
  cancel: string
  retry: string
  /** Back to the photo, from the finished model or an error, with `onStartOver`. */
  startOver: string
  /** Saves the model, with `onDownload`: an icon button, so this is its name and tooltip. */
  download: string
  /** Plays and pauses the model's clip once it's ready: an icon toggle. */
  play: string
  /** Names the style picker, with `styles`. */
  styles: string
  /** Names the bar of controls over the finished model. */
  toolbar: string
  error: string
  progress: (percent: number) => string
}

const modelScanLabels: ModelScanLabels = {
  model: "3D model",
  stage: {
    detecting: "Finding points on the photo",
    building: "Building the 3D model",
    refining: "Refining the shape",
    ready: "The 3D model is ready",
  },
  step: (step, steps) => `Step ${String(step)} of ${String(steps)}`,
  start: "Make 3D",
  cancel: "Cancel",
  retry: "Try again",
  startOver: "Start over",
  download: "Download 3D model",
  play: "Play animation",
  styles: "Style",
  toolbar: "3D model controls",
  error: "The 3D model could not be made",
  progress: (percent) => `${String(percent)}%`,
}

export { modelScanLabels }
export type { ModelScanLabels }

/** A point on the photo, each value a fraction of its width or height from its top left corner. */
type ModelScanPoint = { x: number; y: number }

/** Points as an engine sends them: interleaved x, y pairs, or objects. */
type ModelScanPointList = Float32Array | readonly number[] | readonly ModelScanPoint[]

/** Pairs of point indices in a group that a line joins, like a skeleton's bones. */
type ModelScanEdges = readonly (readonly [number, number])[]

/**
 * One detector's points, like the face or the body, which light up on their own. They are fractions of the original
 * photo; `aspect` is the photo's own width over its height, which lays them out before the photo has loaded. `edges`
 * join them into a mesh; a `body` group of the 33 pose landmarks has the pose skeleton by default.
 */
type ModelScanPointGroup = { source: string; points: ModelScanPointList; aspect?: number; edges?: ModelScanEdges }

/** One list of points, or groups of them; a later group with the same `source` replaces the earlier one. */
type ModelScanPoints = ModelScanPointList | readonly ModelScanPointGroup[]

/**
 * A group ready to draw: every point as interleaved x, y fractions of the photo, kept as sent, and how many of them
 * fall on the photo. Detectors report every landmark, also the ones a crop cut off, past 0 or 1.
 */
type ModelScanDrawnGroup = { source: string; coords: Float32Array; onPhoto: number; edges?: ModelScanEdges }

const poseEdges: ModelScanEdges = [
  [11, 12],
  [11, 13],
  [13, 15],
  [12, 14],
  [14, 16],
  [15, 17],
  [15, 19],
  [17, 19],
  [16, 18],
  [16, 20],
  [18, 20],
  [11, 23],
  [12, 24],
  [23, 24],
  [23, 25],
  [25, 27],
  [24, 26],
  [26, 28],
  [27, 29],
  [29, 31],
  [27, 31],
  [28, 30],
  [30, 32],
  [28, 32],
]

const isGroupList = (points: ModelScanPoints): points is readonly ModelScanPointGroup[] =>
  Array.isArray(points) && points.length > 0 && typeof points[0] === "object" && "source" in points[0]

const isNumberList = (list: readonly number[] | readonly ModelScanPoint[]): list is readonly number[] =>
  list.length > 0 && typeof list[0] === "number"

function interleaved(list: ModelScanPointList) {
  if (ArrayBuffer.isView(list)) return list
  if (isNumberList(list)) return Float32Array.from(list)
  const coords = new Float32Array(list.length * 2)
  list.forEach((point, i) => {
    coords[i * 2] = point.x
    coords[i * 2 + 1] = point.y
  })
  return coords
}

/** Whether a point lies on the photo; one past an edge names a landmark the photo doesn't show. */
const isOnPhoto = (x: number, y: number) => x >= 0 && x <= 1 && y >= 0 && y <= 1

/** Points grouped by source, in the order the sources first arrived. */
function pointGroups(points: ModelScanPoints | undefined): ModelScanDrawnGroup[] {
  if (!points || points.length === 0) return []
  const groups = isGroupList(points) ? points : [{ source: "points", points }]
  const bySource = new Map<string, ModelScanPointGroup>()
  for (const group of groups) bySource.set(group.source, group)
  return [...bySource.values()].map((group) => {
    const coords = interleaved(group.points)
    let onPhoto = 0
    for (let i = 0; i + 1 < coords.length; i += 2) if (isOnPhoto(coords[i] ?? -1, coords[i + 1] ?? -1)) onPhoto += 1
    const edges = group.edges ?? (group.source === "body" && coords.length === 66 ? poseEdges : undefined)
    return edges ? { source: group.source, coords, onPhoto, edges } : { source: group.source, coords, onPhoto }
  })
}

/** The photo's width over its height as the engine reported it, from the first group that has it. */
function pointsAspect(points: ModelScanPoints | undefined) {
  if (!points || !isGroupList(points)) return undefined
  return points.find((group) => group.aspect && Number.isFinite(group.aspect) && group.aspect > 0)?.aspect
}

export { isOnPhoto, pointGroups, pointsAspect, poseEdges }
export type {
  ModelScanDrawnGroup,
  ModelScanEdges,
  ModelScanPoint,
  ModelScanPointGroup,
  ModelScanPointList,
  ModelScanPoints,
}

import type { ModelScanDrawnGroup } from "@/components/ui/model-scan-points"

/**
 * An engine's person mask: 0–255 confidence that a pixel is the person, row-major from the top left, `width` ×
 * `height`, with its photo's aspect. `source` names the photo it was made from.
 */
type ModelScanMask = { source?: "face" | "body"; width: number; height: number; data: Uint8Array }

/** Where the person came from: the engine's mask, a hull around the body's landmarks, or neither yet. */
type ModelScanPersonSource = "mask" | "landmarks" | "none"

const smoothstep = (from: number, to: number, value: number) => {
  const t = Math.min(1, Math.max(0, (value - from) / (to - from)))
  return t * t * (3 - 2 * t)
}

/** The mask's confidence (0 to 1) at a point given as fractions of the photo from its top left, bilinear. */
function sampleMask(mask: ModelScanMask, x: number, y: number) {
  const fx = Math.min(mask.width - 1, Math.max(0, x * mask.width - 0.5))
  const fy = Math.min(mask.height - 1, Math.max(0, y * mask.height - 0.5))
  const x0 = Math.floor(fx)
  const y0 = Math.floor(fy)
  const x1 = Math.min(mask.width - 1, x0 + 1)
  const y1 = Math.min(mask.height - 1, y0 + 1)
  const at = (px: number, py: number) => (mask.data[py * mask.width + px] ?? 0) / 255
  const top = at(x0, y0) + (at(x1, y0) - at(x0, y0)) * (fx - x0)
  const bottom = at(x0, y1) + (at(x1, y1) - at(x0, y1)) * (fx - x0)
  return top + (bottom - top) * (fy - y0)
}

type Capsule = { ax: number; ay: number; bx: number; by: number; r: number }

const limbs: readonly (readonly [number, number, number])[] = [
  [11, 13, 0.14],
  [12, 14, 0.14],
  [13, 15, 0.11],
  [14, 16, 0.11],
  [15, 19, 0.09],
  [16, 20, 0.09],
  [23, 25, 0.2],
  [24, 26, 0.2],
  [25, 27, 0.14],
  [26, 28, 0.14],
  [27, 31, 0.09],
  [28, 32, 0.09],
  [11, 23, 0.12],
  [12, 24, 0.12],
  [11, 12, 0.12],
  [23, 24, 0.16],
]

const segmentDistance = (px: number, py: number, { ax, ay, bx, by }: Capsule) => {
  const dx = bx - ax
  const dy = by - ay
  const t = Math.min(1, Math.max(0, ((px - ax) * dx + (py - ay) * dy) / (dx * dx + dy * dy || 1)))
  return Math.hypot(px - ax - dx * t, py - ay - dy * t)
}

/**
 * A rough silhouette from the 33 pose landmarks when no mask came: capsules around the limbs, the torso filled between
 * shoulders and hips, and the head as a disc over the nose. Coordinates where the photo is `ratio` wide and 1 tall.
 */
function landmarkHull(body: ModelScanDrawnGroup, ratio: number) {
  if (body.coords.length < 66) return null
  const point = (i: number) => ({
    x: (body.coords[i * 2] ?? Number.NaN) * ratio,
    y: body.coords[i * 2 + 1] ?? Number.NaN,
  })
  const known = (i: number) => Number.isFinite(point(i).x) && Number.isFinite(point(i).y)
  if (![11, 12, 23, 24].every(known)) return null
  const [ls, rs] = [point(11), point(12)]
  const shoulders = Math.hypot(ls.x - rs.x, ls.y - rs.y)
  if (shoulders === 0) return null
  const capsules: Capsule[] = limbs
    .filter(([a, b]) => known(a) && known(b))
    .map(([a, b, r]) => ({ ax: point(a).x, ay: point(a).y, bx: point(b).x, by: point(b).y, r: r * shoulders }))
  const torso = [point(11), point(12), point(24), point(23)]
  const nose = known(0) ? point(0) : { x: (ls.x + rs.x) / 2, y: ls.y - shoulders * 0.6 }
  const neck = { x: (ls.x + rs.x) / 2, y: (ls.y + rs.y) / 2 }
  capsules.push({ ax: neck.x, ay: neck.y, bx: nose.x, by: nose.y, r: shoulders * 0.13 })
  const ears = known(7) && known(8) ? Math.hypot(point(7).x - point(8).x, point(7).y - point(8).y) : 0
  const head = { x: nose.x, y: nose.y - shoulders * 0.08, r: Math.max(ears * 0.8, shoulders * 0.32) }
  const inTorso = (x: number, y: number) => {
    let inside = false
    for (let i = 0, j = torso.length - 1; i < torso.length; j = i, i += 1) {
      const [p, q] = [torso[i], torso[j]]
      if (!p || !q) continue
      if (p.y > y !== q.y > y && x < ((q.x - p.x) * (y - p.y)) / (q.y - p.y) + p.x) inside = !inside
    }
    return inside
  }
  const feather = shoulders * 0.04
  return (x: number, y: number) => {
    if (inTorso(x, y)) return 1
    let best = Math.hypot(x - head.x, y - head.y) - head.r
    for (const capsule of capsules) best = Math.min(best, segmentDistance(x, y, capsule) - capsule.r)
    return smoothstep(feather, -feather, best)
  }
}

const hullSize = 128

function hullMask(body: ModelScanDrawnGroup, ratio: number): ModelScanMask | null {
  const hull = landmarkHull(body, ratio)
  if (!hull) return null
  const width = Math.max(1, Math.round(ratio >= 1 ? hullSize : hullSize * ratio))
  const height = Math.max(1, Math.round(ratio >= 1 ? hullSize / ratio : hullSize))
  const data = new Uint8Array(width * height)
  for (let row = 0; row < height; row += 1) {
    for (let column = 0; column < width; column += 1) {
      data[row * width + column] = Math.round(hull(((column + 0.5) / width) * ratio, (row + 0.5) / height) * 255)
    }
  }
  return { source: "body", width, height, data }
}

/**
 * The person in the photo: the engine's body mask, or any mask of the photo's aspect (a face mask over the face
 * photo), else a hull around the body's 33 pose landmarks, else none.
 */
function personMask({
  masks,
  groups,
  ratio,
}: {
  masks?: readonly ModelScanMask[]
  groups: readonly ModelScanDrawnGroup[]
  ratio: number
}): { mask: ModelScanMask | null; from: ModelScanPersonSource } {
  const usable = masks?.filter(
    (mask) => mask.width > 0 && mask.height > 0 && mask.data.length >= mask.width * mask.height,
  )
  const mask =
    usable?.find((item) => item.source === "body") ??
    usable?.find((item) => Math.abs(item.width / item.height / ratio - 1) < 0.02)
  if (mask) return { mask, from: "mask" }
  const body = groups.find((group) => group.source === "body")
  const hull = body ? hullMask(body, ratio) : null
  return hull ? { mask: hull, from: "landmarks" } : { mask: null, from: "none" }
}

/**
 * How much each cell of a `columns` × `rows` grid over the photo is the person, 0 to 1, rows from the bottom as the
 * cloud lays them out; every cell without a mask.
 */
function personCells(columns: number, rows: number, mask: ModelScanMask | null) {
  const cells = new Float32Array(columns * rows)
  for (let row = 0; row < rows; row += 1) {
    const y = 1 - (row + 0.5) / rows
    for (let column = 0; column < columns; column += 1) {
      cells[row * columns + column] = mask ? sampleMask(mask, (column + 0.5) / columns, y) : 1
    }
  }
  return cells
}

/**
 * The mask as two CSS `mask-image` values, the person and the background around them, or null without a 2D canvas
 * (on the server, in a test).
 */
function maskImages(mask: ModelScanMask | null) {
  if (!mask || typeof document === "undefined") return null
  const canvas = document.createElement("canvas")
  canvas.width = mask.width
  canvas.height = mask.height
  const context = canvas.getContext("2d")
  if (!context || typeof context.createImageData !== "function") return null
  const draw = (invert: boolean) => {
    const image = context.createImageData(mask.width, mask.height)
    for (let i = 0; i < mask.width * mask.height; i += 1) {
      const value = mask.data[i] ?? 0
      image.data[i * 4 + 3] = invert ? 255 - value : value
    }
    context.putImageData(image, 0, 0)
    return `url(${canvas.toDataURL()})`
  }
  return { person: draw(false), background: draw(true) }
}

export { landmarkHull, maskImages, personCells, personMask, sampleMask }
export type { ModelScanMask, ModelScanPersonSource }

import { useEffect, useLayoutEffect, useRef } from "react"

const enabledControl =
  "button:not(:disabled,[aria-disabled=true]), select:not(:disabled), a[href], input:not(:disabled,[type=hidden])"

const preferred = [
  `[data-model-scan-primary]:is(${enabledControl})`,
  `[data-model-scan-bar] :is(${enabledControl})`,
  enabledControl,
]

function firstMatch(row: HTMLElement) {
  for (const selector of preferred) {
    const match = row.querySelector<HTMLElement>(selector)
    if (match) return match
  }
  return null
}

const isGone = (element: HTMLElement) => !element.isConnected || element.matches(":disabled, [aria-disabled=true]")

/**
 * Keeps focus in ModelScan's status row across stages. The row's controls change with the stage (a start button
 * goes when the run begins, Cancel when it ends, Retry after an error), so when the control that had focus there is
 * removed or disabled, focus moves to the stage's main control, or the row's first enabled one, instead of falling
 * to the page.
 */
function useModelScanFocus(stage: string) {
  const row = useRef<HTMLDivElement>(null)
  const focused = useRef<HTMLElement | null>(null)
  const shownStage = useRef(stage)

  useEffect(() => {
    const element = row.current
    if (!element) return
    const onFocusIn = (event: FocusEvent) => {
      focused.current = event.target instanceof HTMLElement ? event.target : null
    }
    const onFocusOut = (event: FocusEvent) => {
      if (event.relatedTarget instanceof Node && !element.contains(event.relatedTarget)) focused.current = null
    }
    element.addEventListener("focusin", onFocusIn)
    element.addEventListener("focusout", onFocusOut)
    return () => {
      element.removeEventListener("focusin", onFocusIn)
      element.removeEventListener("focusout", onFocusOut)
    }
  }, [])

  useLayoutEffect(() => {
    if (shownStage.current === stage) return
    shownStage.current = stage
    const element = row.current
    const last = focused.current
    if (!element || !last || !isGone(last)) return
    const active = element.ownerDocument.activeElement
    if (active && active !== last && active !== element.ownerDocument.body) return
    const next = firstMatch(element)
    focused.current = next
    next?.focus()
  })

  return row
}

export { useModelScanFocus }

import { announce, css, definePrimitive, dispatch, prepareAnnouncements, type ChangeDetails } from "@ui-sdk/core"

import { settled, unavailable } from "@/lib/action-refusal"

/**
 * `photo` before anything runs, `detecting` while points light up over it, `building` while the photo turns into
 * the base model, `refining` while weights stream in, `ready` to orbit, `error` to retry.
 */
type ModelScanStage = "photo" | "detecting" | "building" | "refining" | "ready" | "error"

type ModelScanActionReason = "trigger-press" | "imperative"

type ModelScanAnnouncements = {
  stage: (stage: ModelScanStage) => string | undefined
  /** `percent` is a whole number from 0 to 100. */
  progress: (percent: number) => string
  error: string
}

type ModelScanCallback = (value: null, details: ChangeDetails<ModelScanActionReason>) => void

type ModelScanOptions = {
  stage?: ModelScanStage
  /** From 0 to 1 within the stage; undefined while the engine can't tell. */
  progress?: number
  onStart?: ModelScanCallback
  onCancel?: ModelScanCallback
  onRetry?: ModelScanCallback
  onStartOver?: ModelScanCallback
  onDownload?: ModelScanCallback
  /** The photo's width over its height. */
  ratio?: number
  /** The model has taken the photo's place in the 3D scene. */
  introDone?: boolean
  announcements?: ModelScanAnnouncements
}

const working: readonly ModelScanStage[] = ["detecting", "building", "refining"]

type ModelScanAction = "start" | "cancel" | "retry" | "restart" | "download"
type ModelScanCallbackName = "onStart" | "onCancel" | "onRetry" | "onStartOver" | "onDownload"

const actions: Record<ModelScanAction, { callback: ModelScanCallbackName; stages: readonly ModelScanStage[] }> = {
  start: { callback: "onStart", stages: ["photo"] },
  cancel: { callback: "onCancel", stages: working },
  retry: { callback: "onRetry", stages: ["error"] },
  restart: { callback: "onStartOver", stages: ["ready", "error"] },
  download: { callback: "onDownload", stages: ["ready"] },
}

const during: Record<ModelScanStage, string> = {
  photo: "before a scan starts",
  detecting: "while the scan runs",
  building: "while the scan runs",
  refining: "while the scan runs",
  ready: "once the model is ready",
  error: "after an error",
}

const clamp = (value: number) => Math.min(1, Math.max(0, Number.isFinite(value) ? value : 0))

const progressStepPercent = 10
const progressIntervalMs = 2000

const sweepFrames: Keyframe[] = [
  { transform: "translateY(-100%)", opacity: 0 },
  { opacity: 1, offset: 0.12 },
  { opacity: 1, offset: 0.88 },
  { transform: "translateY(294%)", opacity: 0 },
]

const modelScan = definePrimitive({
  name: "model-scan",
  options: {
    stage: "string",
    progress: "number",
    onStart: "callback",
    onCancel: "callback",
    onRetry: "callback",
    onStartOver: "callback",
    onDownload: "callback",
    ratio: "number",
    introDone: "boolean",
    announcements: "value",
  },
  controlled: ["stage"],
  state: (options: ModelScanOptions) => ({
    stage: options.stage ?? "photo",
    progress: options.progress,
    ratio: options.ratio ?? 3 / 4,
    introDone: options.introDone ?? false,
  }),
  sync: (options) => ({
    stage: options.stage ?? "photo",
    progress: options.progress,
    ratio: options.ratio ?? 3 / 4,
    introDone: options.introDone ?? false,
  }),
  api: (context) => {
    const { store } = context
    const run = (action: ModelScanAction, event?: Event) => {
      const reason: ModelScanActionReason = event ? "trigger-press" : "imperative"
      const call = { reason, event }
      const { stage } = store.get()
      const { callback, stages } = actions[action]
      if (!stages.includes(stage)) return unavailable(action, `isn't available ${during[stage]}`, call)
      if (!context.options()[callback]) return unavailable(action, "isn't offered by the app", call)
      return settled(!dispatch(context, callback, null, call), action, call)
    }
    return {
      /** Starts a scan of the photo, through `onStart`. */
      start: (event?: Event) => run("start", event),
      /** Stops the scan while it runs, through `onCancel`. */
      cancel: (event?: Event) => run("cancel", event),
      /** Starts again after an error, through `onRetry`. */
      retry: (event?: Event) => run("retry", event),
      /** Back to the photo from the finished model or an error, through `onStartOver`. */
      restart: (event?: Event) => run("restart", event),
      /** Saves the finished model, through `onDownload`. */
      download: (event?: Event) => run("download", event),
      /** Whether `action` runs in the current stage with the callbacks given. */
      offers: (action: ModelScanAction) =>
        actions[action].stages.includes(store.get().stage) && Boolean(context.options()[actions[action].callback]),
      announcements: () => context.options().announcements,
    }
  },
  slots: (slot) => ({
    root: slot({
      role: "group",
      attrs: (state) => ({
        "data-stage": state.stage,
        "data-intro": state.introDone ? "done" : undefined,
        "aria-busy": working.includes(state.stage) ? "true" : undefined,
        style: css({
          "--model-scan-ratio": String(state.ratio),
          "--model-scan-progress": state.progress === undefined ? undefined : String(clamp(state.progress)),
        }),
      }),
      bind: (el, part) => {
        const doc = el.ownerDocument
        prepareAnnouncements(doc)
        let { stage } = part.store.get()
        let lastStep = -1
        let lastTime = -Infinity
        return part.store.subscribe(() => {
          const state = part.store.get()
          const messages = part.api.announcements()
          if (state.stage !== stage) {
            stage = state.stage
            lastStep = -1
            lastTime = -Infinity
            if (!messages) return
            if (stage === "error") announce(messages.error, { doc, priority: "assertive" })
            else {
              const text = messages.stage(stage)
              if (text) announce(text, { doc })
            }
            return
          }
          if (!working.includes(state.stage) || state.progress === undefined || !messages) return
          const percent = Math.round(clamp(state.progress) * 100)
          const step = Math.floor(percent / progressStepPercent)
          const now = Date.now()
          if (step === lastStep || (now - lastTime < progressIntervalMs && percent < 100)) return
          lastStep = step
          lastTime = now
          announce(messages.progress(percent), { doc })
        })
      },
    }),
    photo: slot<{ handedOff?: boolean }>({
      props: { handedOff: "boolean" },
      attrs: (state, part) => ({
        "data-stage": state.stage,
        "data-handed-off": part.props.handedOff ? "" : undefined,
      }),
    }),
    effect: slot({
      present: (state) => state.stage === "detecting",
      attrs: (state) => ({
        "aria-hidden": "true",
        "data-determinate": state.progress === undefined ? undefined : "",
      }),
      // Spec: a registry component can't ship CSS keyframes, so the sweep is a Web Animation; reduced motion keeps it
      // still.
      bind: (el, part) => {
        const motion = el.ownerDocument.defaultView?.matchMedia?.("(prefers-reduced-motion: reduce)")
        let sweep: Animation | undefined
        const update = () => {
          const beam = el.querySelector<HTMLElement>("[data-beam]")
          const loop =
            part.store.get().progress === undefined && !motion?.matches && typeof beam?.animate === "function"
          if (loop && !sweep && beam) {
            sweep = beam.animate(sweepFrames, {
              duration: 2600,
              iterations: Infinity,
              easing: "cubic-bezier(0.45, 0, 0.55, 1)",
            })
          } else if (!loop && sweep) {
            sweep.cancel()
            sweep = undefined
          }
        }
        update()
        motion?.addEventListener("change", update)
        const unsubscribe = part.store.subscribe(update)
        return () => {
          unsubscribe()
          motion?.removeEventListener("change", update)
          sweep?.cancel()
        }
      },
    }),
    points: slot<{ handedOff?: boolean }>({
      props: { handedOff: "boolean" },
      present: (state, part) => state.stage === "detecting" || (state.stage === "building" && !part.props.handedOff),
      attrs: () => ({ "aria-hidden": "true" }),
    }),
  }),
  agent: { actions: ["start", "cancel", "retry", "restart", "download"] },
})

export { modelScan }
export type { ModelScanAction, ModelScanActionReason, ModelScanAnnouncements, ModelScanOptions, ModelScanStage }

import {
  AdditiveBlending,
  BufferAttribute,
  BufferGeometry,
  Color,
  Mesh,
  NormalBlending,
  PlaneGeometry,
  Points,
  ShaderMaterial,
  SkinnedMesh,
  Vector3,
  type Material,
  type Object3D,
  type Texture,
} from "three"

// Perf: one draw call: every particle's path is a function of `progress` in the vertex shader, so a frame writes
// only uniforms.

const planeVertex = `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`

const timing = `
float liftOf(vec2 spot) { return 0.03 + (1.0 - spot.y) * 0.22; }
const float flight = 0.46;
// The shimmer runs down the body behind the landings, top first; ModelScan's model is revealed under it (shimmerY).
float shimmerOf(float h) { return 0.6 + (1.0 - h) * 0.2; }
`

const photoFragment = `
uniform sampler2D map;
uniform float opacity;
uniform float progress;
varying vec2 vUv;
${timing}
void main() {
  vec4 color = texture2D(map, vUv);
  float gone = smoothstep(liftOf(vUv), liftOf(vUv) + 0.07, progress);
  gl_FragColor = vec4(color.rgb, color.a * opacity * (1.0 - gone));
  #include <colorspace_fragment>
}
`

const cloudVertex = `
attribute vec2 spot;
attribute vec3 goal;
attribute vec3 tint;
attribute vec4 seed;
uniform sampler2D map;
uniform float progress;
uniform vec3 origin;
uniform vec2 size;
uniform float pointSize;
uniform vec3 accent;
uniform vec3 axis;
uniform float floorY;
uniform float height;
uniform float focus;
uniform float additive;
varying vec3 vColor;
varying float vAlpha;
varying float vGlow;
${timing}

vec3 bezier(vec3 a, vec3 b, vec3 c, vec3 d, float t) {
  float s = 1.0 - t;
  return s * s * s * a + 3.0 * s * s * t * b + 3.0 * s * t * t * c + t * t * t * d;
}

vec3 turnY(vec3 p, float angle) {
  vec3 q = p - axis;
  float c = cos(angle);
  float s = sin(angle);
  return axis + vec3(c * q.x + s * q.z, q.y, -s * q.x + c * q.z);
}

void main() {
  vec3 start = origin + vec3((spot - 0.5) * size, 0.0);
  vec3 photo = texture2D(map, spot).rgb;
  float lift = liftOf(spot) + seed.x * 0.06;
  float k = clamp((progress - lift) / flight, 0.0, 1.0);
  float e = 1.0 - pow(1.0 - k, 3.0);
  vec3 position;
  vec3 color;
  float alpha;
  float scale;
  float glow = 0.0;
  if (seed.w > 0.5) {
    // Out towards the camera and away from the body's axis, then in onto the surface from outside it.
    vec3 out1 = normalize(vec3(start.x - axis.x, 0.0, 0.0) + vec3(0.0, 0.0, 1.0)) * height * (0.18 + 0.12 * seed.z);
    vec3 radial = goal - vec3(axis.x, goal.y, axis.z);
    vec3 out2 = (length(radial) > 1e-4 ? normalize(radial) : vec3(0.0, 0.0, 1.0)) * height * (0.14 + 0.1 * seed.y);
    vec3 path = bezier(start, start + out1 + vec3(0.0, height * 0.05, 0.0), goal + out2 + vec3(0.0, height * 0.04, 0.0), goal, e);
    float swirl = (seed.y > 0.5 ? 1.0 : -1.0) * (0.9 + 0.6 * seed.z) * sin(3.14159 * e) * (1.0 - e);
    position = turnY(path, swirl);
    // Photo colour, the accent mid-flight, the surface's own colour on landing.
    color = mix(mix(photo, accent, smoothstep(0.0, 0.4, e)), tint, smoothstep(0.62, 1.0, e));
    float h = clamp((goal.y - floorY) / height, 0.0, 1.0);
    float shimmerAt = shimmerOf(h);
    float shimmer = exp(-pow((progress - shimmerAt) / 0.022, 2.0));
    color = mix(color, accent * mix(1.4, 1.0, additive) + mix(0.15, 0.0, additive), shimmer * mix(0.45, 0.55, additive));
    glow = shimmer;
    alpha = smoothstep(0.0, 0.05, k) * (1.0 - smoothstep(shimmerAt, shimmerAt + 0.04, progress));
    scale = mix(1.0, 0.7, e) * (1.0 + shimmer * 0.7);
  } else {
    vec3 away = vec3((spot.x - 0.5) * 0.6, seed.z * 0.2 - 0.05, 0.25 + seed.x * 0.25);
    position = start + away * height * 0.3 * e;
    color = mix(photo, accent, 0.3 * e);
    alpha = smoothstep(0.0, 0.05, k) * (1.0 - smoothstep(0.05, 0.45, k)) * 0.55;
    scale = 1.0 + 0.2 * e;
  }
  vec4 view = modelViewMatrix * vec4(position, 1.0);
  gl_Position = projectionMatrix * view;
  // A lens's focus: further from the focal plane, bigger and fainter.
  float blur = clamp(abs(-view.z - focus) / focus * 3.0, 0.0, 1.0);
  gl_PointSize = pointSize * scale * (1.0 + blur * 0.8) / -view.z;
  vColor = color;
  vAlpha = alpha / (1.0 + blur * 2.5);
  vGlow = glow;
}
`

const cloudFragment = `
uniform float additive;
varying vec3 vColor;
varying float vAlpha;
varying float vGlow;
void main() {
  float d = length(gl_PointCoord - 0.5) * 2.0;
  if (d > 1.0) discard;
  // A solid disc with a soft rim on a light stage; a gaussian glow, added up, on a dark one.
  float disc = 1.0 - smoothstep(0.55, 1.0, d);
  float glow = exp(-d * d * 4.0);
  float core = exp(-d * d * 16.0);
  vec3 color = vColor * (1.0 + core * (0.2 + vGlow * 0.6) * additive);
  float a = vAlpha * mix(disc, glow * 0.55, additive);
  // Premultiplied when additive, so overlapping sprites brighten instead of turning white at once.
  gl_FragColor = vec4(color * mix(1.0, a, additive), a);
  #include <colorspace_fragment>
}
`

/** Where the shimmer is at `progress`, as a fraction of the model's height from its feet: the shader's shimmerOf. */
const shimmerHeight = (progress: number) => Math.min(1, Math.max(0, 1 - (progress - 0.6) / 0.2))

const seeded = (start: number) => {
  let seed = start
  return () => {
    seed = (seed * 16_807) % 2_147_483_647
    return seed / 2_147_483_647
  }
}

function surfacePoints(root: Object3D, count: number) {
  root.updateMatrixWorld(true)
  const meshes: Mesh[] = []
  root.traverse((object) => {
    if (object instanceof Mesh && !(object.userData as { outline?: boolean }).outline) meshes.push(object)
  })
  const triangles: { mesh: Mesh; a: number; b: number; c: number }[] = []
  const areas: number[] = []
  const [pa, pb, pc] = [new Vector3(), new Vector3(), new Vector3()]
  let total = 0
  for (const mesh of meshes) {
    if (mesh instanceof SkinnedMesh) mesh.skeleton.update()
    const geometry = mesh.geometry
    const position = geometry.getAttribute("position")
    const index = geometry.getIndex()
    const corners = index ? index.count : position.count
    for (let i = 0; i + 2 < corners; i += 3) {
      const [a, b, c] = index ? [index.getX(i), index.getX(i + 1), index.getX(i + 2)] : [i, i + 1, i + 2]
      pa.fromBufferAttribute(position, a)
      pb.fromBufferAttribute(position, b)
      pc.fromBufferAttribute(position, c)
      total += pb.sub(pa).cross(pc.sub(pa)).length() / 2
      triangles.push({ mesh, a, b, c })
      areas.push(total)
    }
  }
  const points = new Float32Array(count * 3)
  const colors = new Float32Array(count * 3).fill(1)
  if (total === 0) return { points, colors }
  const random = seeded(11)
  const tint = new Color()
  const [ca, cb, cc] = [new Color(), new Color(), new Color()]
  for (let i = 0; i < count; i += 1) {
    const pick = random() * total
    let low = 0
    let high = areas.length - 1
    while (low < high) {
      const mid = (low + high) >> 1
      if ((areas[mid] ?? 0) < pick) low = mid + 1
      else high = mid
    }
    const { mesh, a, b, c } = triangles[low]!
    mesh.getVertexPosition(a, pa)
    mesh.getVertexPosition(b, pb)
    mesh.getVertexPosition(c, pc)
    let u = random()
    let v = random()
    if (u + v > 1) {
      u = 1 - u
      v = 1 - v
    }
    pa.multiplyScalar(1 - u - v)
      .addScaledVector(pb, u)
      .addScaledVector(pc, v)
      .applyMatrix4(mesh.matrixWorld)
    points.set([pa.x, pa.y, pa.z], i * 3)
    const vertexColors = (mesh.geometry as BufferGeometry).getAttribute("color")
    const material = [mesh.material].flat()[0] as (Material & { color?: Color }) | undefined
    tint.set(material?.color ?? 0xffffff)
    if (vertexColors) {
      ca.fromBufferAttribute(vertexColors, a)
      cb.fromBufferAttribute(vertexColors, b)
      cc.fromBufferAttribute(vertexColors, c)
      tint.multiply(
        ca
          .multiplyScalar(1 - u - v)
          .add(cb.multiplyScalar(u))
          .add(cc.multiplyScalar(v)),
      )
    }
    colors.set([tint.r, tint.g, tint.b], i * 3)
  }
  return { points, colors }
}

function pairByBands(cells: number[], spots: Float32Array, goals: Float32Array, bands = 56) {
  const order = cells.toSorted((a, b) => (spots[a * 2 + 1] ?? 0) - (spots[b * 2 + 1] ?? 0))
  const targets = Array.from({ length: cells.length }, (_, i) => i).toSorted(
    (a, b) => (goals[a * 3 + 1] ?? 0) - (goals[b * 3 + 1] ?? 0),
  )
  const pairs = new Map<number, number>()
  const per = Math.ceil(cells.length / bands)
  for (let start = 0; start < cells.length; start += per) {
    const band = order.slice(start, start + per).toSorted((a, b) => (spots[a * 2] ?? 0) - (spots[b * 2] ?? 0))
    const goalBand = targets.slice(start, start + per).toSorted((a, b) => (goals[a * 3] ?? 0) - (goals[b * 3] ?? 0))
    band.forEach((cell, i) => pairs.set(cell, goalBand[i] ?? 0))
  }
  return pairs
}

const columns = 150
// Perf: skinned surface samples are the costly part of building the cloud; particles share them, each a little apart.
const surfaceSamples = 5000

function spread(
  samples: { points: Float32Array; colors: Float32Array },
  count: number,
  jitter: number,
  random: () => number,
) {
  const have = samples.points.length / 3
  if (have >= count || have === 0) return samples
  const points = new Float32Array(count * 3)
  const colors = new Float32Array(count * 3)
  for (let i = 0; i < count; i += 1) {
    const from = (i % have) * 3
    for (let axis = 0; axis < 3; axis += 1) {
      points[i * 3 + axis] = (samples.points[from + axis] ?? 0) + (random() - 0.5) * 2 * jitter
      colors[i * 3 + axis] = samples.colors[from + axis] ?? 1
    }
  }
  return { points, colors }
}

/** The cloud's grid: `columns` across the photo, rows by its ratio. */
const cloudGrid = (ratio: number) => ({ columns, rows: Math.max(1, Math.round(columns / ratio)) })

type CloudOptions = {
  texture: Texture
  ratio: number
  accent: Color
  model: Object3D
  /** How much each grid cell is the person, 0 to 1, rows from the bottom (`personCells`); null for the photo alone. */
  person: Float32Array | null
  /** The model's feet, height and vertical axis, in world units. */
  bounds: { center: Vector3; size: Vector3 }
  /** Glowing additive sprites, for a dark stage. */
  dark: boolean
}

/**
 * The photo on a plane, and the cloud its pixels fly in. `set(progress)` plays it from 0 to 1; without `person`
 * there are no particles, only the photo to crossfade with `fade`.
 */
function createCloud({ texture, ratio, accent, model, person, bounds, dark }: CloudOptions) {
  const { rows } = cloudGrid(ratio)
  const cells: number[] = []
  const background: number[] = []
  const random = seeded(23)
  const total = person ? columns * rows : 0
  for (let i = 0; i < total; i += 1) {
    if ((person?.[i] ?? 0) >= 0.5) cells.push(i)
    else if (random() < 0.34) background.push(i)
  }
  const people = cells.length * 2
  const count = people + background.length
  const spots = new Float32Array(count * 2)
  const spotOf = (cell: number, jitter: boolean) => [
    ((cell % columns) + (jitter ? random() : 0.5)) / columns,
    (Math.floor(cell / columns) + (jitter ? random() : 0.5)) / rows,
  ]
  cells.forEach((cell, i) => {
    spots.set(spotOf(cell, true), i * 4)
    spots.set(spotOf(cell, true), i * 4 + 2)
  })
  background.forEach((cell, i) => spots.set(spotOf(cell, false), (people + i) * 2))
  const indices = Array.from({ length: people }, (_, i) => i)
  const surface =
    people > 0
      ? spread(surfacePoints(model, Math.min(people, surfaceSamples)), people, bounds.size.y * 0.006, random)
      : { points: new Float32Array(), colors: new Float32Array() }
  const pairs = pairByBands(indices, spots, surface.points)
  const goals = new Float32Array(count * 3)
  const tints = new Float32Array(count * 3)
  const seeds = new Float32Array(count * 4)
  for (let i = 0; i < count; i += 1) {
    const goal = pairs.get(i)
    if (goal !== undefined) {
      goals.set(surface.points.subarray(goal * 3, goal * 3 + 3), i * 3)
      tints.set(surface.colors.subarray(goal * 3, goal * 3 + 3), i * 3)
    }
    seeds.set([random(), random(), random(), goal === undefined ? 0 : 1], i * 4)
  }
  const uniforms = {
    map: { value: texture },
    progress: { value: 0 },
    opacity: { value: 1 },
    accent: { value: accent.clone() },
    origin: { value: new Vector3() },
    size: { value: [1, 1] },
    pointSize: { value: 1 },
    axis: { value: new Vector3(bounds.center.x, 0, bounds.center.z) },
    floorY: { value: bounds.center.y - bounds.size.y / 2 },
    height: { value: bounds.size.y },
    focus: { value: 1 },
    additive: { value: dark ? 1 : 0 },
  }
  const photo = new Mesh(
    new PlaneGeometry(1, 1),
    new ShaderMaterial({
      uniforms,
      vertexShader: planeVertex,
      fragmentShader: photoFragment,
      transparent: true,
      depthTest: false,
    }),
  )
  photo.renderOrder = 1
  const geometry = new BufferGeometry()
  geometry.setAttribute("position", new BufferAttribute(new Float32Array(count * 3), 3))
  geometry.setAttribute("spot", new BufferAttribute(spots, 2))
  geometry.setAttribute("goal", new BufferAttribute(goals, 3))
  geometry.setAttribute("tint", new BufferAttribute(tints, 3))
  geometry.setAttribute("seed", new BufferAttribute(seeds, 4))
  const cloud = new Points(
    geometry,
    new ShaderMaterial({
      uniforms,
      vertexShader: cloudVertex,
      fragmentShader: cloudFragment,
      transparent: true,
      depthWrite: false,
      depthTest: false,
      blending: dark ? AdditiveBlending : NormalBlending,
      premultipliedAlpha: dark,
    }),
  )
  cloud.frustumCulled = false
  cloud.renderOrder = 2
  cloud.visible = count > 0
  const material = cloud.material as ShaderMaterial
  return {
    objects: [photo, cloud] as Object3D[],
    particles: count,
    people,
    place(center: Vector3, width: number, height: number, pixels: number, focus: number) {
      photo.position.copy(center)
      photo.scale.set(width, height, 1)
      uniforms.origin.value.copy(center)
      uniforms.size.value = [width, height]
      uniforms.pointSize.value = (width / columns) * pixels * 1.5
      uniforms.focus.value = focus
    },
    set(progress: number) {
      uniforms.progress.value = progress
    },
    theme(next: Color, onDark: boolean) {
      uniforms.accent.value.copy(next)
      uniforms.additive.value = onDark ? 1 : 0
      const blending = onDark ? AdditiveBlending : NormalBlending
      if (material.blending === blending) return
      material.blending = blending
      material.premultipliedAlpha = onDark
      material.needsUpdate = true
    },
    fade(opacity: number) {
      uniforms.opacity.value = opacity
      cloud.visible = false
    },
    hide() {
      photo.visible = false
      cloud.visible = false
    },
    dispose() {
      photo.geometry.dispose()
      ;(photo.material as ShaderMaterial).dispose()
      geometry.dispose()
      ;(cloud.material as ShaderMaterial).dispose()
    },
  }
}

type Cloud = ReturnType<typeof createCloud>

export { cloudGrid, createCloud, shimmerHeight }
export type { Cloud }

import { useFrame, useThree } from "@react-three/fiber"
import { use, useEffect, useMemo, useRef, useState } from "react"
import {
  Color,
  Group,
  Plane,
  SRGBColorSpace,
  TextureLoader,
  Vector3,
  type Object3D,
  type PerspectiveCamera,
  type Texture,
} from "three"

import { cloudGrid, createCloud, shimmerHeight, type Cloud } from "@/components/ui/model-scan-cloud"
import { personCells, type ModelScanMask, type ModelScanPersonSource } from "@/components/ui/model-scan-mask"
import { fitSize, viewSizeAt } from "@/components/ui/model-viewer-math"
import { isMesh } from "@/components/ui/model-viewer-meshes"
import type { ModelViewerHandle } from "@/components/ui/model-viewer-primitive"
import { ModelViewerSceneContext, type ModelRig } from "@/components/ui/model-viewer-rig"
import { isDark, onThemeChange, tokenColor } from "@/components/ui/model-viewer-theme"
import { assumeType } from "@/lib/narrow"

const flightSeconds = 3.4
const crossfade = 0.7

const smoothstep = (from: number, to: number, value: number) => {
  const t = Math.min(1, Math.max(0, (value - from) / (to - from)))
  return t * t * (3 - 2 * t)
}

function turn(handle: ModelViewerHandle) {
  handle.api.setView("three-quarter")
  handle.api.aim("three-quarter")
}

// Perf: a clipping plane compiles the model's materials again: done on the first frame, under the 2D photo, and once the
// cloud has landed.
function setClipping(root: Object3D, planes: Plane[] | null) {
  root.traverse((object) => {
    if (!isMesh(object)) return
    for (const material of [object.material].flat()) {
      material.clippingPlanes = planes
      material.needsUpdate = true
    }
  })
}

function createReveal() {
  const plane = new Plane(new Vector3(0, 1, 0), 0)
  return {
    plane,
    above(y: number) {
      plane.constant = -y
    },
  }
}

type IntroOptions = {
  src: string
  /** The photo's width over its height. */
  ratio: number
  /** How the photo fills a stage of another ratio, as the 2D one is drawn. */
  fit: "contain" | "cover"
  /** The person in the photo, whose pixels fly onto the model; without one, every pixel does. */
  mask: ModelScanMask | null
  /** Where the mask came from, written on the canvas for tooling. */
  person: ModelScanPersonSource
  /** The 3D photo matches the 2D one: the 2D layer can go. */
  onHandOff: () => void
  /** The model has taken the photo's place. */
  onDone: () => void
}

/**
 * The photo on a plane where the front camera sees it exactly as the 2D photo was drawn, then, once the model has
 * loaded, the camera turns to the three-quarter view while the person's pixels fly onto the model's surface, a
 * shimmer runs down it revealing the model, and a pulse runs across the floor. Under reduced motion the photo
 * crossfades into the model and the camera jumps after.
 */
function useModelScanIntro({ src, ratio, fit, mask, person, onHandOff, onDone }: IntroOptions) {
  const scene = use(ModelViewerSceneContext)
  // Workaround: R3F types `state.camera` as any `Camera`; the model viewer's canvas isn't `orthographic`, so it is R3F's default
  // PerspectiveCamera.
  const camera = assumeType<PerspectiveCamera>(useThree((state) => state.camera))
  const gl = useThree((state) => state.gl)
  const invalidate = useThree((state) => state.invalidate)
  const [texture, setTexture] = useState<{ src: string; texture: Texture | null } | null>(null)

  useEffect(() => {
    let current: Texture | undefined
    let cancelled = false
    new TextureLoader().loadAsync(src).then(
      (loaded) => {
        loaded.colorSpace = SRGBColorSpace
        if (cancelled) {
          loaded.dispose()
          return
        }
        current = loaded
        setTexture({ src, texture: loaded })
      },
      () => {
        if (!cancelled) setTexture({ src, texture: null })
      },
    )
    return () => {
      cancelled = true
      current?.dispose()
    }
  }, [src])

  const group = useMemo(() => new Group(), [])
  const cloud = useRef<Cloud | null>(null)
  useEffect(
    () => () => {
      if (!cloud.current) return
      group.remove(...cloud.current.objects)
      cloud.current.dispose()
      cloud.current = null
    },
    [group],
  )
  const colors = useMemo(() => ({ accent: new Color(), background: new Color() }), [])
  useEffect(() => {
    const read = () => {
      tokenColor(gl.domElement, "--info", 0x3b82f6, colors.accent)
      tokenColor(gl.domElement, "--background", 0xffffff, colors.background)
      cloud.current?.theme(colors.accent, isDark(colors.background))
      invalidate()
    }
    read()
    return onThemeChange(read)
  }, [gl, colors, invalidate])

  const reveal = useMemo(() => createReveal(), [])
  const clipped = useRef<ModelRig | null>(null)
  const rig = scene?.rig
  const floor = scene?.floor
  useEffect(
    () => () => {
      rig?.setOpacity(1)
      floor?.set({ opacity: 1, pulse: 0 })
      if (clipped.current) setClipping(clipped.current.scene, null)
      clipped.current = null
    },
    [rig, floor],
  )
  // Spec: the canvas draws on demand, and the intro moves only inside a frame: once the photo's texture and the model are
  // both here, ask for one. Without it, a texture that loads after the scene has gone still never starts the intro.
  const loaded = texture?.src === src && rig !== undefined && rig !== null
  useEffect(() => {
    if (loaded) invalidate()
  }, [loaded, invalidate])

  const handOff = () => onHandOff()
  const done = () => onDone()
  const clock = useRef({ frames: 0, start: -1, aimed: false, finished: false })
  const center = useMemo(() => new Vector3(), [])

  useFrame((state) => {
    if (!scene || !rig || !texture || texture.src !== src || clock.current.finished) return
    const { handle, framing } = scene
    const reduced = handle.get().reducedMotion
    const intro = clock.current
    const map = texture.texture
    if (!map) {
      intro.finished = true
      handOff()
      turn(handle)
      done()
      return
    }
    const bounds = rig.bounds
    const feet = bounds.center.y - bounds.size.y / 2
    const framed = rig.frame(framing, camera)
    center.copy(framed.center)
    const view = viewSizeAt(framed.distance, camera.fov, camera.aspect)
    const photo = fitSize(ratio, view, fit)
    const pixels = state.gl.domElement.height / (2 * Math.tan(((camera.fov / 2) * Math.PI) / 180))

    intro.frames += 1
    if (intro.frames === 1) {
      state.gl.localClippingEnabled = true
      handle.api.aim("front", "jump")
      floor?.set({ opacity: 0, pulse: 0 })
      const built = performance.now()
      const grid = cloudGrid(ratio)
      cloud.current = createCloud({
        texture: map,
        ratio,
        accent: colors.accent,
        model: rig.scene,
        person: reduced ? null : personCells(grid.columns, grid.rows, mask),
        bounds,
        dark: isDark(colors.background),
      })
      group.add(...cloud.current.objects)
      if (reduced) rig.setOpacity(0)
      else rig.setOpacity(1)
      const canvas = state.gl.domElement.dataset
      canvas.particles = String(cloud.current.particles)
      canvas.person = person
      canvas.cloudMs = (performance.now() - built).toFixed(1)
    }
    if (!reduced && clipped.current !== rig) {
      if (clipped.current) setClipping(clipped.current.scene, null)
      setClipping(rig.scene, [reveal.plane])
      clipped.current = rig
      if (intro.start < 0) reveal.above(feet + bounds.size.y * 1.1)
    }
    if (intro.frames === 3) {
      handOff()
      intro.start = state.clock.elapsedTime
    }
    cloud.current?.place(center, photo.width, photo.height, pixels, camera.position.distanceTo(center))
    state.invalidate()
    if (intro.start < 0) return

    const u = (state.clock.elapsedTime - intro.start) / (reduced ? crossfade : flightSeconds)
    if (reduced) {
      cloud.current?.fade(1 - smoothstep(0, 1, u))
      rig.setOpacity(smoothstep(0, 1, u))
      floor?.set({ opacity: smoothstep(0, 1, u) })
    } else {
      if (!intro.aimed && u > 0.08) {
        intro.aimed = true
        turn(handle)
      }
      cloud.current?.set(u)
      reveal.above(feet + bounds.size.y * (shimmerHeight(u) - 0.03))
      floor?.set({ opacity: smoothstep(0.05, 0.5, u), pulse: u > 0.72 ? smoothstep(0.72, 1, u) : 0 })
    }
    if (u < 1) return
    intro.finished = true
    cloud.current?.hide()
    floor?.set({ opacity: 1, pulse: 0 })
    if (clipped.current) setClipping(clipped.current.scene, null)
    clipped.current = null
    rig.setOpacity(1)
    if (reduced) turn(handle)
    invalidate()
    done()
  })

  return group
}

